        {
          "id": "WriteYamlValue",
          "node_type": "Action",
          "subcategory": "YAML Operations",
          "description": "\n                <p>\n                    Sets a value at a nested key path in a YAML file. Companion to\n                    <code>ReadYamlValue</code>; takes the file location as a single\n                    <code>file_path</code> port that accepts an absolute path, an absolute path\n                    with <code>${VAR}</code> / leading <code>~</code> expansion, or a ROS\n                    <code>package://&lt;pkg&gt;/&lt;rest&gt;</code> URL.\n                </p>\n                <p>\n                    The <code>value</code> port is parsed as YAML before being stored, so scalars\n                    (<code>\"B\"</code>), inline maps (<code>\"{ option: A, success: false }\"</code>),\n                    and sequences (<code>\"[a, b, c]\"</code>) all flow through the same string port.\n                    Intermediate maps along <code>key1..key5</code> are created if missing; an\n                    existing value at the leaf is overwritten.\n                </p>\n                <p>\n                    Round-trips through yaml-cpp on every tick: load existing &rarr; modify &rarr; dump.\n                    The dump is written to a temporary file alongside the target and renamed over it,\n                    so a reader never observes a half-written file. The load-modify-write is held under\n                    an exclusive lock on a <code>&lt;file&gt;.lock</code> sidecar next to the target, so\n                    two writers of one file cannot each load the same document and have the later one\n                    discard the earlier one's edit. Fails the tick if the file does not exist, or if a\n                    key along <code>key1..key5</code> holds a scalar and so cannot be descended into.\n                </p>\n            ",
          "ports": [
            {
              "name": "file_path",
              "direction": "input",
              "type": "std::string",
              "default": null,
              "description": "Path to the YAML file. Accepts an absolute path (/home/user/foo.yaml), an absolute path with shell-style ${VAR} / leading ~ expansion (${HOME}/foo.yaml), or a ROS package URL (package://my_pkg/config/foo.yaml resolves via ament_index_cpp::get_package_share_directory)."
            },
            {
              "name": "key1",
              "direction": "input",
              "type": "std::string",
              "default": null,
              "description": "First key to traverse YAML structure (mandatory)"
            },
            {
              "name": "key2",
              "direction": "input",
              "type": "std::string",
              "default": "",
              "description": "Second key (optional)"
            },
            {
              "name": "key3",
              "direction": "input",
              "type": "std::string",
              "default": "",
              "description": "Third key (optional)"
            },
            {
              "name": "key4",
              "direction": "input",
              "type": "std::string",
              "default": "",
              "description": "Fourth key (optional)"
            },
            {
              "name": "key5",
              "direction": "input",
              "type": "std::string",
              "default": "",
              "description": "Fifth key (optional)"
            },
            {
              "name": "value",
              "direction": "input",
              "type": "std::string",
              "default": null,
              "description": "Value to write at the keyed location. Parsed as YAML, so scalars, inline maps (`{ key: val, ... }`), and sequences (`[a, b, c]`) all work through the same string port."
            }
          ]
        }
